LEGACY_RECORDS = [{'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/node_supply_demand.csv', 'values': {'Node': 'S1', 'NodeType': 'SourceSupply', 'Amount': '120'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/node_supply_demand.csv', 'values': {'Node': 'S2', 'NodeType': 'SourceSupply', 'Amount': '100'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/node_supply_demand.csv', 'values': {'Node': 'S3', 'NodeType': 'SourceSupply', 'Amount': '90'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/node_supply_demand.csv', 'values': {'Node': 'C1', 'NodeType': 'CustomerDemand', 'Amount': '70'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/node_supply_demand.csv', 'values': {'Node': 'C2', 'NodeType': 'CustomerDemand', 'Amount': '80'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/node_supply_demand.csv', 'values': {'Node': 'C3', 'NodeType': 'CustomerDemand', 'Amount': '60'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/node_supply_demand.csv', 'values': {'Node': 'C4', 'NodeType': 'CustomerDemand', 'Amount': '90'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/hub_capacity.csv', 'values': {'Hub': 'H1', 'ThroughputCapacity': '170'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/hub_capacity.csv', 'values': {'Hub': 'H2', 'ThroughputCapacity': '160'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/arc_costs.csv', 'values': {'From': 'S1', 'To': 'H1', 'Cost': '2'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/arc_costs.csv', 'values': {'From': 'S1', 'To': 'H2', 'Cost': '6'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/arc_costs.csv', 'values': {'From': 'S2', 'To': 'H1', 'Cost': '4'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/arc_costs.csv', 'values': {'From': 'S2', 'To': 'H2', 'Cost': '3'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/arc_costs.csv', 'values': {'From': 'S3', 'To': 'H1', 'Cost': '7'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/arc_costs.csv', 'values': {'From': 'S3', 'To': 'H2', 'Cost': '2'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/arc_costs.csv', 'values': {'From': 'H1', 'To': 'C1', 'Cost': '3'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/arc_costs.csv', 'values': {'From': 'H1', 'To': 'C2', 'Cost': '4'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/arc_costs.csv', 'values': {'From': 'H1', 'To': 'C3', 'Cost': '7'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/arc_costs.csv', 'values': {'From': 'H1', 'To': 'C4', 'Cost': '8'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/arc_costs.csv', 'values': {'From': 'H2', 'To': 'C1', 'Cost': '8'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/arc_costs.csv', 'values': {'From': 'H2', 'To': 'C2', 'Cost': '6'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/arc_costs.csv', 'values': {'From': 'H2', 'To': 'C3', 'Cost': '3'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant7/inputs/arc_costs.csv', 'values': {'From': 'H2', 'To': 'C4', 'Cost': '4'}}]
import gurobipy as gp
from gurobipy import GRB
node_supply = {}
node_demand = {}
sources = []
customers = []
hubs = []
hub_capacity = {}
arc_cost = {}
arcs = []
for rec in LEGACY_RECORDS:
    v = rec['values']
    if rec['source'].endswith('node_supply_demand.csv'):
        node = v['Node']
        if v['NodeType'] == 'SourceSupply':
            sources.append(node)
            node_supply[node] = float(v['Amount'])
        elif v['NodeType'] == 'CustomerDemand':
            customers.append(node)
            node_demand[node] = float(v['Amount'])
    elif rec['source'].endswith('hub_capacity.csv'):
        hub = v['Hub']
        hubs.append(hub)
        hub_capacity[hub] = float(v['ThroughputCapacity'])
    elif rec['source'].endswith('arc_costs.csv'):
        i = v['From']
        j = v['To']
        cost = float(v['Cost'])
        arc_cost[i, j] = cost
        arcs.append((i, j))
for s in sources:
    for h in hubs:
        if (s, h) not in arc_cost:
            raise ValueError(f'Missing arc cost for ({s},{h})')
for h in hubs:
    for c in customers:
        if (h, c) not in arc_cost:
            raise ValueError(f'Missing arc cost for ({h},{c})')
m = gp.Model('min_cost_transshipment')
f_vars = m.addVars(arcs, lb=0, vtype=GRB.CONTINUOUS, name='')
m.setObjective(gp.quicksum((arc_cost[arc] * f_vars[arc] for arc in arcs)), GRB.MINIMIZE)
for s in sources:
    m.addConstr(gp.quicksum((f_vars[s, h] for h in hubs)) <= node_supply[s], name=f'supply_{s}')
for c in customers:
    m.addConstr(gp.quicksum((f_vars[h, c] for h in hubs)) >= node_demand[c], name=f'demand_{c}')
for h in hubs:
    m.addConstr(gp.quicksum((f_vars[s, h] for s in sources)) == gp.quicksum((f_vars[h, c] for c in customers)), name=f'flowbal_{h}')
for h in hubs:
    m.addConstr(gp.quicksum((f_vars[s, h] for s in sources)) <= hub_capacity[h], name=f'cap_{h}')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')